 17	interface ShippingMethod {
 18	    String code();
 19	
 20	    /** Verdadeiro se a opção tem frete (a retirada na loja não tem). */
 21	    boolean chargesShipping();
 22	
 23	    /** Verdadeiro se o frete pode ser isentado por vantagem do clube (falso para serviço terceirizado). */
