 43	class CarrierShippingMethod implements ShippingMethod {
 44	    private final String code;
 45	    private final String service;
 46	    private final CarrierGateway gateway;
 47	
 48	    CarrierShippingMethod(String code, String service, CarrierGateway gateway) {
 49	        this.code = code;
 50	        this.service = service;
 51	        this.gateway = gateway;
 52	    }
 53	
 54	    public String code() { return code; }
 55	
 56	    public boolean chargesShipping() { return true; }
 57	
 58	    public boolean waivableByClub() { return true; }
 59	
 60	    public ShippingQuote quote(ShippingContext ctx) {
 61	        Optional<CarrierQuote> quote;
 62	        try {
 63	            quote = gateway.quote(ctx.zipCode(), ctx.weightGrams(), service);
 64	        } catch (CarrierDownException e) {
 65	            throw new ApiException("CARRIER_UNAVAILABLE", 503);
 66	        }
 67	        CarrierQuote q = quote.orElseThrow(() -> ApiException.unprocessable("SHIPPING_METHOD_UNAVAILABLE"));
 68	        int days = (q.etaHours() + 23) / 24 + ctx.region().carrierExtraDays();
 69	        return new ShippingQuote(Money.round(q.price()), days);
 70	    }
 71	}
 72	
 73	class StorePickupShippingMethod implements ShippingMethod {
 74	    public String code() { return "STORE_PICKUP"; }
 75	
 76	    public boolean chargesShipping() { return false; }
 77	
 78	    public boolean waivableByClub() { return true; }
 79	
 80	    public ShippingQuote quote(ShippingContext ctx) {
 81	        return new ShippingQuote(Money.ZERO, 1);
 82	    }
 83	}
 84	
 85	class CourierShippingMethod implements ShippingMethod {
 86	    private static final BigDecimal MAX_WEIGHT_KG = new BigDecimal("5");
 87	
 88	    public String code() { return "COURIER"; }
 89	
 90	    public boolean chargesShipping() { return true; }
 91	
 92	    public boolean waivableByClub() { return false; }
 93	
 94	    public ShippingQuote quote(ShippingContext ctx) {
 95	        if (ctx.weightKg().compareTo(MAX_WEIGHT_KG) > 0) {
 96	            throw ApiException.unprocessable("SHIPPING_METHOD_UNAVAILABLE");
 97	        }
 98	        return new ShippingQuote(new BigDecimal("18.00"), 0);
 99	    }
100	}
101	
102	final class ShippingMethods {
103	    private final Map<String, ShippingMethod> byCode = new LinkedHashMap<>();
104	
105	    ShippingMethods(ShippingMethod... methods) {
106	        for (ShippingMethod m : methods) byCode.put(m.code(), m);
107	    }
108	
109	    static ShippingMethods standard(CarrierGateway carrier) {
110	        return new ShippingMethods(
111	                new CarrierShippingMethod("ECONOMY", "STD", carrier),
112	                new CarrierShippingMethod("EXPRESS", "EXP", carrier),
113	                new StorePickupShippingMethod(),
114	                new CourierShippingMethod());
115	    }
116	
117	    ShippingMethod get(String code) {
118	        return code == null ? null : byCode.get(code);
119	    }
120	}
