136	class TransLogGateway implements CarrierGateway {
137	    private static final ObjectMapper MAPPER = new ObjectMapper();
138	    private static final long TIMEOUT_MS = 2000;
139	
140	    private final String baseUrl;
141	    private final HttpClient client = HttpClient.newBuilder().connectTimeout(Duration.ofMillis(TIMEOUT_MS)).build();
142	
143	    TransLogGateway(String baseUrl) {
144	        this.baseUrl = baseUrl == null ? null : baseUrl.replaceAll("/+$", "");
145	    }
146	
147	    @Override
148	    public Optional<CarrierQuote> quote(String zipCode, long weightGrams, String service) {
149	        if (baseUrl == null || baseUrl.isBlank()) throw new CarrierDownException("TRANSLOG_URL not set", null);
150	        CompletableFuture<HttpResponse<String>> future = null;
151	        try {
152	            URI uri = URI.create(baseUrl + "/v2/quote?zip=" + zipCode + "&weight_g=" + weightGrams + "&service=" + service);
153	            HttpRequest request = HttpRequest.newBuilder(uri).GET().build();
154	            future = client.sendAsync(request, HttpResponse.BodyHandlers.ofString());
155	            HttpResponse<String> response = future.get(TIMEOUT_MS, TimeUnit.MILLISECONDS);
156	            if (response.statusCode() != 200) throw new CarrierDownException("status " + response.statusCode(), null);
157	            return parse(response.body());
158	        } catch (CarrierDownException e) {
159	            throw e;
160	        } catch (InterruptedException e) {
161	            Thread.currentThread().interrupt();
162	            throw new CarrierDownException("interrupted", e);
163	        } catch (Exception e) {
164	            throw new CarrierDownException("TransLog failure", e);
165	        } finally {
166	            if (future != null) future.cancel(true);
167	        }
168	    }
169	
170	    private static Optional<CarrierQuote> parse(String body) throws Exception {
171	        JsonNode json = MAPPER.readTree(body);
172	        if (json == null || !json.isObject()) throw new CarrierDownException("unexpected body", null);
173	        JsonNode error = json.get("error");
174	        if (error != null) {
175	            if (error.isTextual() && error.asText().equals("ZIP_NOT_SERVED")) return Optional.empty();
176	            throw new CarrierDownException("carrier error", null);
177	        }
178	        JsonNode price = json.get("price_cents");
179	        JsonNode eta = json.get("eta_hours");
180	        if (price == null || eta == null || !price.isIntegralNumber() || !eta.isIntegralNumber()
181	                || !price.canConvertToLong() || !eta.canConvertToInt() || price.asLong() < 0 || eta.asInt() < 0) {
182	            throw new CarrierDownException("unexpected body", null);
183	        }
184	        return Optional.of(new CarrierQuote(BigDecimal.valueOf(price.asLong(), 2), eta.asInt()));
185	    }
